def move(apps, schema_editor):
    """The storage places stop being tags of a group of the company and become a list of each
    warehouse (customer's decision of 22.11.2026). What a unit or a lot had as tags becomes one
    place of its warehouse — the first of its tags by name; then the links, the tags and the
    group of the places are removed from the tags."""
    group_model = apps.get_model("tags", "TagGroup")
    tag_model = apps.get_model("tags", "Tag")
    link_model = apps.get_model("tags", "TagLink")
    place_model = apps.get_model("warehouse", "StoragePlace")
    groups = list(group_model.objects.filter(code="storage_places"))
    if not groups:
        return
    tags = tag_model.objects.filter(group__in=groups)
    places = {}
    for model, kind in (("Asset", "warehouse_asset"), ("Lot", "warehouse_lot")):
        record_model = apps.get_model("warehouse", model)
        links = (
            link_model.objects.filter(object_type=kind, tag__in=tags)
            .order_by("object_id", "tag__name_key")
            .values_list("object_id", "tag__name")
        )
        first = {}
        for object_id, name in links:
            first.setdefault(object_id, name)
        for record in record_model.objects.filter(pk__in=list(first)):
            name = " ".join(first[record.pk].split())
            key = (record.context_id, name.lower())
            if key not in places:
                places[key] = place_model.objects.create(
                    company_id=record.company_id,
                    context_id=record.context_id,
                    name=name,
                    name_key=name.lower(),
                )
            record.place = places[key]
            record.save(update_fields=["place"])
    link_model.objects.filter(tag__in=tags).delete()
    tags.delete()
    for group in groups:
        group.delete()


